<?php require_student(); $errors=[]; $categories=db_all('SELECT id,category_name FROM categories ORDER BY category_name'); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$category=(int)($_POST['category_id']??0);$priority=$_POST['priority']??'Medium';if(strlen($title)<5)$errors[]='Title must be at least 5 characters.';if(strlen($description)<20)$errors[]='Description must be at least 20 characters.';if(!in_array($priority,['Low','Medium','High'],true))$errors[]='Select a valid priority.';if(!db_one('SELECT id FROM categories WHERE id=?','i',[$category]))$errors[]='Select a valid category.';$attachment=null;if(!$errors&&isset($_FILES['attachment'])&&$_FILES['attachment']['error']!==UPLOAD_ERR_NO_FILE){$attachment=allowed_upload($_FILES['attachment']);if(!$attachment)$errors[]='Attachment must be a PDF, DOC, DOCX, JPG, JPEG, or PNG under 2 MB.';}if(!$errors){$cid='CC-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$stmt=db()->prepare('INSERT INTO complaints (complaint_id,student_id,category_id,title,description,priority,attachment) VALUES (?,?,?,?,?,?,?)');$sid=student()['id'];$stmt->bind_param('siissss',$cid,$sid,$category,$title,$description,$priority,$attachment);if($stmt->execute()){flash('success','Complaint '.$cid.' submitted successfully.');redirect('student/my-complaints.php');}$errors[]='Could not submit the complaint.';}}$pageTitle='Submit Complaint';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="small-muted">STUDENT PORTAL</div><h1 class="section-title mb-0">Submit a complaint</h1><p class="text-secondary mb-0 mt-2">Please include enough detail for the team to investigate your concern.</p></div><div class="card"><div class="card-body"><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $item): ?><li><?=e($item)?></li><?php endforeach;?></ul></div><?php endif; ?><form method="post" enctype="multipart/form-data" data-validate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Complaint title</label><input class="form-control" name="title" required minlength="5" maxlength="180" value="<?=e($_POST['title']??'')?>" placeholder="e.g. Projector not working in Room 204"></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Category</label><select class="form-select" name="category_id" required><option value="">Choose a category</option><?php foreach($categories as $cat): ?><option value="<?=$cat['id']?>" <?=((int)($_POST['category_id']??0)===$cat['id'])?'selected':''?>><?=e($cat['category_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Priority</label><select class="form-select" name="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></div></div><div class="mb-3 mt-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="6" required minlength="20" placeholder="Describe what happened, where, and when."><?=e($_POST['description']??'')?></textarea></div><div class="mb-4"><label class="form-label">Supporting attachment <span class="small-muted">(optional, max 2 MB)</span></label><input class="form-control" type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"></div><button class="btn btn-primary px-4" type="submit">Submit complaint</button></form></div></div></div></div>
